for (let i = 0; i < n; i++) {
  for (let j = 0; j < m; j++) {
    const nd = new Int32Array(1 << m);
    for (let mask = 0; mask < (1 << m); mask++) {
      const ways = dp[mask];
      if (ways === 0) continue;
      if ((mask >> j) & 1) {
        const t = mask ^ (1 << j);
        nd[t] = (nd[t] + ways) % MOD;
      } else if (grid[i][j] === '#') {
        nd[mask] = (nd[mask] + ways) % MOD;
