        if (i + 1 < n && grid[i + 1][j] === '.') {
          const t = mask | (1 << j);
          nd[t] = (nd[t] + ways) % MOD;
        }
        if (j + 1 < m && grid[i][j + 1] === '.' && !((mask >> (j + 1)) & 1)) {
          const t = mask | (1 << (j + 1));
          nd[t] = (nd[t] + ways) % MOD;
        }
      }
    }
