#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (auto &row : grid) cin >> row;
    const long long MOD = 1000000007LL;
    vector<long long> dp(1 << m, 0), nd(1 << m);
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            fill(nd.begin(), nd.end(), 0);
            for (int mask = 0; mask < (1 << m); mask++) {
                long long ways = dp[mask];
                if (!ways) continue;
                if ((mask >> j) & 1) {
                    int t = mask ^ (1 << j);
                    nd[t] = (nd[t] + ways) % MOD;
                } else if (grid[i][j] == '#') {
                    nd[mask] = (nd[mask] + ways) % MOD;
                } else {
                    if (i + 1 < n && grid[i + 1][j] == '.') {
                        int t = mask | (1 << j);
                        nd[t] = (nd[t] + ways) % MOD;
                    }
                    if (j + 1 < m && grid[i][j + 1] == '.' && !((mask >> (j + 1)) & 1)) {
                        int t = mask | (1 << (j + 1));
                        nd[t] = (nd[t] + ways) % MOD;
                    }
                }
            }
            swap(dp, nd);
        }
    }
    cout << dp[0] << endl;
    return 0;
}
